     */
    public long daysLate(InvoiceStatus status, LocalDate today) {
        if (status != InvoiceStatus.SENT && status != InvoiceStatus.PARTIAL) {
            return 0;
        }
        return Math.max(0, ChronoUnit.DAYS.between(dueDate, today));
    }

